/**
 * Secrets each deployed sites Worker needs (names and purposes only, never values). Checked before
 * every deploy by scripts/release/check-secrets.ts (`--ensure` generates a missing SESSION_SECRET
 * once: it is a random key nobody needs to know).
 */
import { ENVIRONMENTS, type EnvName } from './environments.ts';

export interface RequiredSecret {
  name: string;
  purpose: string;
  /** Can be generated by the release itself (a random key no other system shares) */
  generate?: () => string;
}

export const SESSION_SECRET: RequiredSecret = {
  name: 'SESSION_SECRET',
  purpose: 'worker secret, 64 hex chars; AES-GCM key of the host-only __Host-aun_site session and sign-in cookies',
  generate: () => Array.from(crypto.getRandomValues(new Uint8Array(32)), (b) => b.toString(16).padStart(2, '0')).join(''),
};

export const SECRETS_MANIFEST = (Object.keys(ENVIRONMENTS) as EnvName[]).map((env) => ({ env, worker: ENVIRONMENTS[env].worker, required: [SESSION_SECRET] }));
